#![allow(dead_code)]
#[path="../handheld/src/core_admission.rs"]mod core_admission;
#[path="../handheld/src/key_diag_core.rs"]mod key_diag_core;
#[path="../handheld/src/core_coordinator.rs"]mod core_coordinator;
use core_coordinator::{Coordinator,Maintenance};
#[test]fn idle_observation_does_not_reserve_or_mutate(){let mut c=Coordinator::new();for _ in 0..4{assert!(c.lab_reboot_quiet(false));assert!(c.lab_reboot_quiet(true));}let p=c.maintenance(Maintenance::Benchmark).unwrap();assert!(!c.lab_reboot_quiet(false));c.maintenance_finished(p,true).unwrap();assert!(c.lab_reboot_quiet(false));}
#[test]fn pending_and_active_receiver_block_even_claimed_lab_completion(){let mut c=Coordinator::new();c.receiver_request().unwrap();assert!(!c.lab_reboot_quiet(false));assert!(!c.lab_reboot_quiet(true));c.source_dequeued();c.receiver_active().unwrap();assert!(!c.lab_reboot_quiet(true));c.receiver_stopped(true).unwrap();assert!(c.lab_reboot_quiet(false));}
#[test]fn av_coexistence_is_not_mistaken_for_completed_native_lab(){let mut c=Coordinator::new();c.receiver_request().unwrap();c.source_dequeued();c.receiver_active().unwrap();c.av_admit().unwrap();assert!(!c.lab_reboot_quiet(false));assert!(!c.lab_reboot_quiet(true));}
#[test]fn active_native_held_native_and_maintenance_are_distinct(){for(kind,held_allowed)in[(Maintenance::Benchmark,true),(Maintenance::Rate,false),(Maintenance::Restore,false)]{let mut c=Coordinator::new();let permit=c.maintenance(kind).unwrap();assert!(!c.lab_reboot_quiet(false));assert_eq!(c.lab_reboot_quiet(true),held_allowed);c.maintenance_finished(permit,true).unwrap();assert!(c.lab_reboot_quiet(false));}}
#[test]fn program_and_diagnostic_permits_block_recovery_until_released(){let mut c=Coordinator::new();let p=c.program(false,false).unwrap();assert!(!c.lab_reboot_quiet(true));c.program_finished(p,false).unwrap();assert!(c.lab_reboot_quiet(false));let p=c.diagnostic().unwrap();assert!(!c.lab_reboot_quiet(true));c.unissued_diagnostic_finished(p).unwrap();assert!(c.lab_reboot_quiet(false));}
#[test]fn quarantined_held_lab_can_restart_without_lease_release(){let mut c=Coordinator::new();let _held=c.maintenance(Maintenance::Benchmark).unwrap();c.quarantine();assert!(!c.lab_reboot_quiet(false));assert!(c.lab_reboot_quiet(true));assert!(c.quarantined());assert!(c.receiver_request().is_err());assert!(c.maintenance(Maintenance::Rate).is_err());assert!(c.lab_reboot_quiet(true));}
#[test]fn quiet_snapshot_alone_is_not_a_delayed_reboot_barrier(){let mut c=Coordinator::new();assert!(c.lab_reboot_quiet(false));let _new_native_worker=c.maintenance(Maintenance::Benchmark).unwrap();assert!(!c.lab_reboot_quiet(false));/* Integration must reserve/revalidate before deferred callback. */}

#[test]fn pending_recovery_blocks_every_new_coordinator_admission_and_repeat(){let mut c=Coordinator::new();assert!(c.lab_reboot_begin(false));assert!(!c.lab_reboot_quiet(false));assert!(!c.lab_reboot_quiet(true));assert!(!c.lab_reboot_begin(false));assert!(!c.lab_reboot_begin(true));assert!(c.receiver_request().is_err());assert!(c.av_admit().is_err());for(receiver,restore)in[(false,false),(true,false),(false,true),(true,true)]{assert!(c.program(receiver,restore).is_err());}assert!(c.diagnostic().is_err());for kind in [Maintenance::Benchmark,Maintenance::Rate,Maintenance::Restore]{assert!(c.maintenance(kind).is_err());}assert!(c.restore_begin().is_err());}
#[test]fn failed_scheduling_cancel_restores_normal_admission(){let mut c=Coordinator::new();assert!(c.lab_reboot_begin(false));c.lab_reboot_cancel();assert!(c.lab_reboot_quiet(false));assert!(!c.quarantined());let p=c.diagnostic().unwrap();c.unissued_diagnostic_finished(p).unwrap();let p=c.program(false,false).unwrap();c.program_finished(p,false).unwrap();let p=c.maintenance(Maintenance::Benchmark).unwrap();c.maintenance_finished(p,true).unwrap();c.receiver_request().unwrap();}
#[test]fn cancel_preserves_quarantine_and_held_lease(){let mut c=Coordinator::new();let held=c.maintenance(Maintenance::Benchmark).unwrap();c.quarantine();assert!(!c.lab_reboot_begin(false));assert!(c.lab_reboot_begin(true));c.lab_reboot_cancel();assert!(c.quarantined());assert!(!c.lab_reboot_quiet(false));assert!(c.lab_reboot_quiet(true));assert!(c.receiver_request().is_err());assert!(c.program(false,true).is_err());assert!(c.maintenance(Maintenance::Rate).is_err());c.maintenance_finished(held,true).unwrap();assert!(c.quarantined());assert!(c.receiver_request().is_err());}
#[test]fn completed_held_benchmark_allows_barrier_but_running_work_does_not(){let mut c=Coordinator::new();let _held=c.maintenance(Maintenance::Benchmark).unwrap();assert!(!c.lab_reboot_begin(false));assert!(c.lab_reboot_begin(true));assert!(!c.lab_reboot_begin(true));assert!(c.diagnostic().is_err());assert!(c.program(false,true).is_err());}
